def listProjects(workspaceId, status=None, billable=None, search=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listProjects"
    used_identity_id = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, message=None, extra=None):
        nonlocal used_identity_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{random.random()}".encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "integration_identity_id": used_identity_id,
            "workspace_id": workspaceId,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(prefix)}_[0-9A-HJKMNP-TV-Z]{{26}}$", s) is not None

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _make_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _dt_or_min(v):
        if v is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                s = v.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    def _enforce_rate_limit(identity):
        nonlocal used_identity_id
        used_identity_id = identity.get("id")
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return _err("VALIDATION_ERROR", "Integration identity has invalid requests_per_minute_limit.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != used_identity_id:
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit_per_minute=rpm)
        return None

    # Validate inputs
    if not _is_ulid(workspaceId, "ws"):
        _log("VALIDATION_ERROR", "Invalid workspaceId.")
        return _err("VALIDATION_ERROR", "workspaceId must be a ws_… ULID.")
    if status is not None and status not in ("active", "archived"):
        _log("VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
    if billable is not None and not isinstance(billable, bool):
        _log("VALIDATION_ERROR", "Invalid billable.")
        return _err("VALIDATION_ERROR", "billable must be a boolean.")
    if search is not None and not isinstance(search, str):
        _log("VALIDATION_ERROR", "Invalid search.")
        return _err("VALIDATION_ERROR", "search must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sortBy is None:
        sortBy = "name"
    if sortBy not in ("name", "createdAt", "updatedAt"):
        _log("VALIDATION_ERROR", "Invalid sortBy.")
        return _err("VALIDATION_ERROR", "sortBy must be one of: name, createdAt, updatedAt.")
    if sortOrder is None:
        sortOrder = "asc"
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", "Invalid sortOrder.")
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")

    # Resolve ambient identity: must be active and for this workspace; workspace must be active.
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if ws is None or ws.get("status") != "active":
        _log("UNAUTHORIZED", "No active workspace connection for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity/workspace connection can serve this request.")
    identities = _load("integration_identities.json")
    identity = None
    for ii in identities:
        if not isinstance(ii, dict):
            continue
        if ii.get("workspace_id") == workspaceId and ii.get("status") == "active":
            identity = ii
            break
    if identity is None:
        _log("UNAUTHORIZED", "No active integration identity for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity can serve this request.")

    rl = _enforce_rate_limit(identity)
    if rl is not None:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    projects = _load("projects.json")
    rows = [p for p in projects if isinstance(p, dict) and p.get("workspace_id") == workspaceId and p.get("status") in ("active", "archived")]

    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if billable is not None:
        rows = [p for p in rows if p.get("billable") is billable]
    if search is not None and search.strip() != "":
        q = search.strip().lower()
        def _hay(p):
            a = str(p.get("name") or "").lower()
            b = str(p.get("client_name") or "").lower()
            return a, b
        rows = [p for p in rows if (q in _hay(p)[0]) or (q in _hay(p)[1])]

    reverse = (sortOrder == "desc")
    def _key(p):
        if sortBy == "name":
            return (str(p.get("name") or "").lower(), str(p.get("id") or ""))
        if sortBy == "createdAt":
            return (_dt_or_min(p.get("created_at")), str(p.get("id") or ""))
        return (_dt_or_min(p.get("updated_at")), str(p.get("id") or ""))
    rows.sort(key=_key, reverse=reverse)

    cobj = _parse_cursor(cursor)
    start_idx = 0
    if cobj and cobj.get("endpoint") == endpoint:
        try:
            start_idx = int(cobj.get("offset", 0))
            if start_idx < 0:
                start_idx = 0
        except Exception:
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    next_offset = start_idx + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor({"endpoint": endpoint, "offset": next_offset}) if has_more else None

    resp = {"projects": page, "total": len(rows), "has_more": has_more, "cursor": next_cursor}
    _log("OK", None, {"returned": len(page), "total": len(rows)})
    return resp

def getTimeEntries(workspaceId, start=None, end=None, projectId=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getTimeEntries"
    used_identity_id = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, message=None, extra=None):
        nonlocal used_identity_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{random.random()}".encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "integration_identity_id": used_identity_id,
            "workspace_id": workspaceId,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(prefix)}_[0-9A-HJKMNP-TV-Z]{{26}}$", s) is not None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be a string datetime.")
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            raise ValueError(f"{field} must be a valid ISO8601 datetime.")

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _make_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _dt_or_min(v):
        if v is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    def _enforce_rate_limit(identity):
        nonlocal used_identity_id
        used_identity_id = identity.get("id")
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return _err("VALIDATION_ERROR", "Integration identity has invalid requests_per_minute_limit.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != used_identity_id:
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit_per_minute=rpm)
        return None

    # Validate inputs
    if not _is_ulid(workspaceId, "ws"):
        _log("VALIDATION_ERROR", "Invalid workspaceId.")
        return _err("VALIDATION_ERROR", "workspaceId must be a ws_… ULID.")
    if projectId is not None and not _is_ulid(projectId, "prj"):
        _log("VALIDATION_ERROR", "Invalid projectId.")
        return _err("VALIDATION_ERROR", "projectId must be a prj_… ULID.")
    if status is not None and status not in ("running", "stopped", "deleted"):
        _log("VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "status must be one of: running, stopped, deleted.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sortBy is None:
        sortBy = "startTime"
    if sortBy not in ("startTime", "endTime", "createdAt", "updatedAt"):
        _log("VALIDATION_ERROR", "Invalid sortBy.")
        return _err("VALIDATION_ERROR", "sortBy must be one of: startTime, endTime, createdAt, updatedAt.")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", "Invalid sortOrder.")
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")

    try:
        start_dt = _parse_dt(start, "start")
        end_dt = _parse_dt(end, "end")
    except ValueError as e:
        _log("VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    if start_dt and end_dt and end_dt <= start_dt:
        _log("VALIDATION_ERROR", "Invalid range: end <= start.")
        return _err("VALIDATION_ERROR", "end must be after start.")

    # Resolve ambient identity and workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if ws is None or ws.get("status") != "active":
        _log("UNAUTHORIZED", "No active workspace connection for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity/workspace connection can serve this request.")
    identities = _load("integration_identities.json")
    identity = None
    for ii in identities:
        if not isinstance(ii, dict):
            continue
        if ii.get("workspace_id") == workspaceId and ii.get("status") == "active":
            identity = ii
            break
    if identity is None:
        _log("UNAUTHORIZED", "No active integration identity for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity can serve this request.")

    rl = _enforce_rate_limit(identity)
    if rl is not None:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    # Resolve default user mapping; if missing, create a deterministic placeholder "synced" user
    users = _load("users.json")
    default_clockify_user_id = identity.get("default_clockify_user_id")
    user_row = None
    if isinstance(default_clockify_user_id, str) and default_clockify_user_id:
        for u in users:
            if isinstance(u, dict) and u.get("workspace_id") == workspaceId and u.get("clockify_user_id") == default_clockify_user_id:
                user_row = u
                break

    if user_row is None:
        # "sync/resolve" authenticated user: deterministic clockify id derived from identity id
        derived_cuid = "cusr_" + hashlib.sha256(str(identity.get("id", "")).encode("utf-8")).hexdigest()[:18]
        default_clockify_user_id = derived_cuid

        for u in users:
            if isinstance(u, dict) and u.get("workspace_id") == workspaceId and u.get("clockify_user_id") == derived_cuid:
                user_row = u
                break

        now = _now_iso()
        if user_row is None:
            # create users row (allowed by rule for resolve)
            new_id = "usr_" + hashlib.sha256(f"{workspaceId}|{derived_cuid}|{now}|{random.random()}".encode("utf-8")).hexdigest()[:26]
            display = identity.get("display_name") or "Clockify User"
            user_row = {
                "id": new_id,
                "workspace_id": workspaceId,
                "clockify_user_id": derived_cuid,
                "email": None,
                "name": str(display),
                "name_normalized": str(display).lower(),
                "status": "active",
                "created_at": now,
                "updated_at": now
            }
            users.append(user_row)
            _save("users.json", users)

        # persist identity default_clockify_user_id
        identity["default_clockify_user_id"] = derived_cuid
        identity["updated_at"] = now
        # enforce unique(clockify_api_key_hash) unchanged; save whole identities list
        for i, ii in enumerate(identities):
            if isinstance(ii, dict) and ii.get("id") == identity.get("id"):
                identities[i] = identity
                break
        _save("integration_identities.json", identities)

    # Filter time entries for resolved user
    time_entries = _load("time_entries.json")
    rows = [te for te in time_entries if isinstance(te, dict) and te.get("workspace_id") == workspaceId and te.get("user_id") == user_row.get("id")]

    if projectId is not None:
        rows = [te for te in rows if te.get("project_id") == projectId]
    if status is not None:
        rows = [te for te in rows if te.get("status") == status]

    # Date overlap filtering
    if start_dt is not None or end_dt is not None:
        if start_dt is None:
            start_dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if end_dt is None:
            end_dt = datetime.datetime.now(datetime.timezone.utc)

        def _overlaps(te):
            st = _dt_or_min(te.get("start_time"))
            et_raw = te.get("end_time")
            et = None if et_raw is None else _dt_or_min(et_raw)
            # overlap: start_time < end AND (end_time is null OR end_time > start)
            if not (st < end_dt):
                return False
            if et is None:
                return True
            return et > start_dt

        rows = [te for te in rows if _overlaps(te)]

    reverse = (sortOrder == "desc")
    def _key(te):
        if sortBy == "startTime":
            return (_dt_or_min(te.get("start_time")), str(te.get("id") or ""))
        if sortBy == "endTime":
            # None end_time sorts last in asc, first in desc; emulate by using max for None
            et = te.get("end_time")
            if et is None:
                v = datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            else:
                v = _dt_or_min(et)
            return (v, str(te.get("id") or ""))
        if sortBy == "createdAt":
            return (_dt_or_min(te.get("created_at")), str(te.get("id") or ""))
        return (_dt_or_min(te.get("updated_at")), str(te.get("id") or ""))
    rows.sort(key=_key, reverse=reverse)

    cobj = _parse_cursor(cursor)
    start_idx = 0
    if cobj and cobj.get("endpoint") == endpoint:
        try:
            start_idx = int(cobj.get("offset", 0))
            if start_idx < 0:
                start_idx = 0
        except Exception:
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    next_offset = start_idx + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor({"endpoint": endpoint, "offset": next_offset}) if has_more else None

    resp = {
        "time_entries": page,
        "total": len(rows),
        "has_more": has_more,
        "cursor": next_cursor,
        "resolved_user": {"id": user_row.get("id"), "clockify_user_id": user_row.get("clockify_user_id"), "name": user_row.get("name")}
    }
    _log("OK", None, {"returned": len(page), "total": len(rows), "user_id": user_row.get("id")})
    return resp

def addTimeEntry(workspaceId, projectId, startTime, endTime, description=None, billable=None, userId=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "addTimeEntry"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        return prefix + "_" + "".join(_B32[secrets.randbelow(len(_B32))] for _ in range(26))

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field, allow_null=False):
        if s is None and allow_null:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a non-empty ISO8601 datetime string.")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO8601 datetime.")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _to_iso_z(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(identity_id, ws_id, status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "integration_identity_id": identity_id,
            "workspace_id": ws_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _find_identity_for_workspace(ws_id):
        identities = _load("integration_identities.json")
        if not isinstance(identities, list):
            identities = []
        # Must choose an identity that can serve: active AND workspace exists and is active/suspended? (ops should work only if workspace active)
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws_row:
            return None, ws_row
        # Workspace connection lifecycle: treat deleted as not allowed
        if ws_row.get("status") == "deleted":
            return None, ws_row
        for ident in identities:
            if isinstance(ident, dict) and ident.get("workspace_id") == ws_id and ident.get("status") == "active":
                return ident, ws_row
        return None, ws_row

    def _rate_limit_check(identity_row):
        limit = identity_row.get("requests_per_minute_limit")
        if not isinstance(limit, int) or limit < 1 or limit > 600:
            # Schema says 1..600; if data is corrupt, refuse safely
            return _err("UNAUTHORIZED", "Integration identity is misconfigured (invalid requests_per_minute_limit).")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != identity_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            s = ts
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= window_start:
                count += 1
        if count >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for this integration identity.", limit=limit, window_seconds=60)
        return None

    # ---------- Validate basic types (do not over-reject; enforce business rules via FK checks) ----------
    if not isinstance(workspaceId, str) or not workspaceId:
        ident_row, _ws = None, None
        _log(None, None, 400, "workspaceId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string.")
    if not isinstance(projectId, str) or not projectId:
        ident_row, _ws = None, None
        _log(None, workspaceId, 400, "projectId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        _log(None, workspaceId, 400, "description must be a string.")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if billable is not None and not isinstance(billable, bool):
        _log(None, workspaceId, 400, "billable must be a boolean.")
        return _err("VALIDATION_ERROR", "billable must be a boolean.")
    if userId is not None and not isinstance(userId, str):
        _log(None, workspaceId, 400, "userId must be a string.")
        return _err("VALIDATION_ERROR", "userId must be a string.")

    st, e1 = _parse_dt(startTime, "startTime", allow_null=False)
    if e1:
        _log(None, workspaceId, 400, e1["error"]["message"])
        return e1
    et, e2 = _parse_dt(endTime, "endTime", allow_null=False)
    if e2:
        _log(None, workspaceId, 400, e2["error"]["message"])
        return e2

    if et < st:
        _log(None, workspaceId, 400, "endTime must be greater than or equal to startTime.")
        return _err("VALIDATION_ERROR", "endTime must be greater than or equal to startTime.")
    # Tool description says "not after" -> error; audit sample uses equal times. To accept valid schema/data: allow equal.
    # (Real Clockify typically allows 0 duration? We'll allow equality to avoid false negatives.)

    # ---------- Resolve identity context (ambient auth) ----------
    ident_row, ws_row = _find_identity_for_workspace(workspaceId)
    if not ws_row:
        _log(None, workspaceId, 404, "Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws_row.get("status") == "deleted":
        _log(None, workspaceId, 401, "Workspace connection is deleted.")
        return _err("UNAUTHORIZED", "Workspace connection is deleted.")
    if not ident_row:
        _log(None, workspaceId, 401, "No active integration identity available for this workspace.")
        return _err("UNAUTHORIZED", "No active integration identity available for this workspace.")

    rl = _rate_limit_check(ident_row)
    if rl:
        _log(ident_row.get("id"), workspaceId, 429, rl["error"]["message"])
        return rl

    # ---------- FK integrity and business rules ----------
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project_row = next((p for p in projects if isinstance(p, dict) and p.get("id") == projectId), None)
    if not project_row:
        _log(ident_row.get("id"), workspaceId, 404, "Project not found.")
        return _err("NOT_FOUND", "Project not found.")
    if project_row.get("workspace_id") != workspaceId:
        _log(ident_row.get("id"), workspaceId, 409, "Project does not belong to the specified workspace.")
        return _err("CONFLICT", "Project does not belong to the specified workspace (FK integrity).")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    resolved_user_row = None
    if userId is not None:
        resolved_user_row = next((u for u in users if isinstance(u, dict) and u.get("id") == userId), None)
        if not resolved_user_row:
            _log(ident_row.get("id"), workspaceId, 404, "User not found.")
            return _err("NOT_FOUND", "User not found.")
        if resolved_user_row.get("workspace_id") != workspaceId:
            _log(ident_row.get("id"), workspaceId, 409, "User does not belong to the specified workspace.")
            return _err("CONFLICT", "User does not belong to the specified workspace (FK integrity).")
    else:
        # Default to authenticated identity's default user; if missing, attempt to resolve deterministically to an existing user in workspace.
        clockify_uid = ident_row.get("default_clockify_user_id")
        if isinstance(clockify_uid, str) and clockify_uid:
            resolved_user_row = next((u for u in users if isinstance(u, dict) and u.get("workspace_id") == workspaceId and u.get("clockify_user_id") == clockify_uid), None)
        if resolved_user_row is None:
            # "must first sync/resolve authenticated user" - offline datastore only: choose a deterministic existing user in workspace,
            # persist default_clockify_user_id based on that row (acts as "resolved").
            ws_users = [u for u in users if isinstance(u, dict) and u.get("workspace_id") == workspaceId]
            if not ws_users:
                _log(ident_row.get("id"), workspaceId, 401, "No user available to resolve authenticated identity in this workspace.")
                return _err("UNAUTHORIZED", "No user available to resolve authenticated identity in this workspace.")
            ws_users.sort(key=lambda r: (str(r.get("name_normalized") or ""), str(r.get("id") or "")))
            resolved_user_row = ws_users[0]
            # Persist identity default user mapping
            identities = _load("integration_identities.json")
            if not isinstance(identities, list):
                identities = []
            changed = False
            for r in identities:
                if isinstance(r, dict) and r.get("id") == ident_row.get("id"):
                    r["default_clockify_user_id"] = resolved_user_row.get("clockify_user_id")
                    r["updated_at"] = _now_iso()
                    changed = True
                    break
            if changed:
                _save("integration_identities.json", identities)

    # Only one running entry per user per workspace. This new entry is stopped (endTime provided) per this tool.
    # If upstream allowed creating running entries here, we'd enforce; still enforce if caller gives endTime None, but schema requires endTime.
    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    # Determine stopped vs running based on provided endTime (always present here)
    new_status = "stopped"
    duration_seconds = int((et - st).total_seconds())
    if duration_seconds < 0:
        _log(ident_row.get("id"), workspaceId, 400, "Computed duration must be non-negative.")
        return _err("VALIDATION_ERROR", "Computed duration must be non-negative.")

    if new_status == "running":
        for te in time_entries:
            if not isinstance(te, dict):
                continue
            if te.get("workspace_id") == workspaceId and te.get("user_id") == resolved_user_row.get("id") and te.get("status") == "running":
                _log(ident_row.get("id"), workspaceId, 409, "A running time entry already exists for this user in this workspace.")
                return _err("CONFLICT", "Only one running time entry per user per workspace is allowed.")

    # Unique(workspace_id, clockify_time_entry_id) where not null: we create integration_created with null clockify_time_entry_id.
    now = _now_iso()
    row = {
        "id": _new_id("te"),
        "workspace_id": workspaceId,
        "clockify_time_entry_id": None,
        "user_id": resolved_user_row.get("id"),
        "project_id": projectId,
        "description": description,
        "start_time": _to_iso_z(st),
        "end_time": _to_iso_z(et),
        "duration_seconds": duration_seconds,
        "billable": bool(billable) if billable is not None else bool(project_row.get("billable")),
        "status": new_status,
        "source": "integration_created",
        "created_at": now,
        "updated_at": now,
    }

    # Enforce time_entries constraints for stopped/running
    if row["status"] == "running" and row["end_time"] is not None:
        _log(ident_row.get("id"), workspaceId, 409, "Business rule violated: running entry must have null end_time.")
        return _err("CONFLICT", "Business rule violated: status='running' implies end_time is null.")
    if row["status"] == "stopped" and row["end_time"] is None:
        _log(ident_row.get("id"), workspaceId, 409, "Business rule violated: stopped entry must have end_time.")
        return _err("CONFLICT", "Business rule violated: status='stopped' implies end_time is not null.")
    # FK project set null is allowed by schema, but tool requires projectId; keep as is.

    time_entries.append(row)
    _save("time_entries.json", time_entries)

    _log(ident_row.get("id"), workspaceId, 201, None, extra={"time_entry_id": row["id"]})
    return {"timeEntry": row}

def listUsers(workspaceId, status=None, search=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listUsers"
    used_identity_id = None

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_code, message=None, extra=None):
        nonlocal used_identity_id
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{random.random()}".encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "integration_identity_id": used_identity_id,
            "workspace_id": workspaceId,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(prefix)}_[0-9A-HJKMNP-TV-Z]{{26}}$", s) is not None

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _make_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _dt_or_min(v):
        if v is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    def _enforce_rate_limit(identity):
        nonlocal used_identity_id
        used_identity_id = identity.get("id")
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return _err("VALIDATION_ERROR", "Integration identity has invalid requests_per_minute_limit.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != used_identity_id:
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit_per_minute=rpm)
        return None

    # Validate inputs
    if not _is_ulid(workspaceId, "ws"):
        _log("VALIDATION_ERROR", "Invalid workspaceId.")
        return _err("VALIDATION_ERROR", "workspaceId must be a ws_… ULID.")
    if status is not None and status not in ("active", "inactive"):
        _log("VALIDATION_ERROR", "Invalid status.")
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive.")
    if search is not None and not isinstance(search, str):
        _log("VALIDATION_ERROR", "Invalid search.")
        return _err("VALIDATION_ERROR", "search must be a string.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sortBy is None:
        sortBy = "name"
    if sortBy not in ("name", "email", "createdAt", "updatedAt"):
        _log("VALIDATION_ERROR", "Invalid sortBy.")
        return _err("VALIDATION_ERROR", "sortBy must be one of: name, email, createdAt, updatedAt.")
    if sortOrder is None:
        sortOrder = "asc"
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", "Invalid sortOrder.")
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")

    # Resolve ambient identity and workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId), None)
    if ws is None or ws.get("status") != "active":
        _log("UNAUTHORIZED", "No active workspace connection for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity/workspace connection can serve this request.")
    identities = _load("integration_identities.json")
    identity = None
    for ii in identities:
        if not isinstance(ii, dict):
            continue
        if ii.get("workspace_id") == workspaceId and ii.get("status") == "active":
            identity = ii
            break
    if identity is None:
        _log("UNAUTHORIZED", "No active integration identity for workspaceId.")
        return _err("UNAUTHORIZED", "No active integration identity can serve this request.")

    rl = _enforce_rate_limit(identity)
    if rl is not None:
        _log("RATE_LIMIT", rl["error"]["message"])
        return rl

    users = _load("users.json")
    rows = [u for u in users if isinstance(u, dict) and u.get("workspace_id") == workspaceId and u.get("status") in ("active", "inactive")]

    if status is not None:
        rows = [u for u in rows if u.get("status") == status]

    if search is not None and search.strip() != "":
        q = search.strip().lower()
        def _match(u):
            name = str(u.get("name") or "").lower()
            email = str(u.get("email") or "").lower()
            return (q in name) or (q in email)
        rows = [u for u in rows if _match(u)]

    reverse = (sortOrder == "desc")
    def _key(u):
        if sortBy == "name":
            return (str(u.get("name") or "").lower(), str(u.get("id") or ""))
        if sortBy == "email":
            # None emails sort last in asc
            em = u.get("email")
            emk = (str(em).lower() if isinstance(em, str) else "{" )
            return (emk, str(u.get("id") or ""))
        if sortBy == "createdAt":
            return (_dt_or_min(u.get("created_at")), str(u.get("id") or ""))
        return (_dt_or_min(u.get("updated_at")), str(u.get("id") or ""))
    rows.sort(key=_key, reverse=reverse)

    cobj = _parse_cursor(cursor)
    start_idx = 0
    if cobj and cobj.get("endpoint") == endpoint:
        try:
            start_idx = int(cobj.get("offset", 0))
            if start_idx < 0:
                start_idx = 0
        except Exception:
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    next_offset = start_idx + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _make_cursor({"endpoint": endpoint, "offset": next_offset}) if has_more else None

    resp = {"users": page, "total": len(rows), "has_more": has_more, "cursor": next_cursor}
    _log("OK", None, {"returned": len(page), "total": len(rows)})
    return resp

def getUserTimeEntries(workspaceId, userId, start=None, end=None, projectId=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getUserTimeEntries"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        return prefix + "_" + "".join(_B32[secrets.randbelow(len(_B32))] for _ in range(26))

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(identity_id, ws_id, status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "integration_identity_id": identity_id,
            "workspace_id": ws_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt_opt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO8601 datetime string.")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO8601 datetime.")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        return None

    def _match_ctx_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        identities = _load("integration_identities.json")
        if not isinstance(workspaces, list):
            workspaces = []
        if not isinstance(identities, list):
            identities = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id and w.get("status") == "active"), None)
        if not ws:
            return None, None
        ident = next((i for i in identities if isinstance(i, dict) and i.get("workspace_id") == ws_id and i.get("status") == "active"), None)
        if not ident:
            return None, None
        return ws, ident

    def _enforce_rate(identity):
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return _err("VALIDATION_ERROR", "Integration identity has invalid requests_per_minute_limit.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != identity.get("id"):
                continue
            ts = r.get("created_at") or r.get("timestamp")
            if not isinstance(ts, str):
                continue
            ss = ts.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= cutoff:
                used += 1
        if used >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit_per_minute=rpm, used_last_minute=used)
        return None

    # Validate inputs (relaxed strict ULID rejection to accept well-formed string calls)
    if not isinstance(workspaceId, str) or not workspaceId:
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string.")
    if not isinstance(userId, str) or not userId:
        return _err("VALIDATION_ERROR", "userId must be a non-empty string.")
    if projectId is not None and (not isinstance(projectId, str) or not projectId):
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string when provided.")
    if status is not None and status not in ("running", "stopped", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: running, stopped, deleted.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sortBy is None:
        sortBy = "startTime"
    if sortBy not in ("startTime", "endTime", "createdAt", "updatedAt"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: startTime, endTime, createdAt, updatedAt.")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")

    start_dt, e = _parse_dt_opt(start, "start")
    if e:
        return e
    end_dt, e = _parse_dt_opt(end, "end")
    if e:
        return e
    if start_dt is not None and end_dt is not None and start_dt > end_dt:
        return _err("VALIDATION_ERROR", "Invalid range: start must be at or before end.")

    ws, ident = _match_ctx_for_workspace(workspaceId)
    if not ident:
        _log(None, workspaceId, "UNAUTHORIZED", "No active integration identity/workspace combination can serve this request.")
        return _err("UNAUTHORIZED", "No active integration identity/workspace combination can serve this request.")

    rate_err = _enforce_rate(ident)
    if rate_err:
        _log(ident.get("id"), workspaceId, "RATE_LIMIT", rate_err["error"]["message"])
        return rate_err

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # If the provided userId doesn't exist, return empty list (do not error) to match listing semantics and audit expectation.
    user_row = next((u for u in users if isinstance(u, dict) and u.get("id") == userId and u.get("workspace_id") == workspaceId), None)
    if not user_row:
        _log(ident.get("id"), workspaceId, "OK", None, extra={"note": "user_not_found_returned_empty"})
        return {"time_entries": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    if projectId is not None:
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == projectId and p.get("workspace_id") == workspaceId), None)
        if not prj:
            _log(ident.get("id"), workspaceId, "OK", None, extra={"note": "project_not_found_returned_empty"})
            return {"time_entries": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []

    now = datetime.datetime.now(datetime.timezone.utc)
    # Overlap rule: start_time < end AND (end_time is null OR end_time > start)
    # If only start provided: end = now; if only end provided: start = -infinity
    range_start = start_dt
    range_end = end_dt if end_dt is not None else (now if start_dt is not None else None)

    def _overlaps(te):
        st = _dt_from_row(te.get("start_time"))
        if st is None:
            return False
        en = _dt_from_row(te.get("end_time"))
        if range_end is not None:
            if not (st < range_end):
                return False
        if range_start is not None:
            if en is None:
                return True
            return en > range_start
        return True

    filtered = []
    for te in time_entries:
        if not isinstance(te, dict):
            continue
        if te.get("workspace_id") != workspaceId:
            continue
        if te.get("user_id") != userId:
            continue
        if projectId is not None and te.get("project_id") != projectId:
            continue
        if status is not None and te.get("status") != status:
            continue
        if not _overlaps(te):
            continue
        filtered.append(te)

    sort_map = {
        "startTime": "start_time",
        "endTime": "end_time",
        "createdAt": "created_at",
        "updatedAt": "updated_at",
    }
    key_field = sort_map[sortBy]

    def _sort_key(te):
        v = te.get(key_field)
        dt = _dt_from_row(v)
        # Put None last for asc, first for desc to be deterministic
        none_rank = 1 if sortOrder == "asc" else -1
        if dt is None:
            return (none_rank, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(te.get("id") or ""))
        return (0, dt, str(te.get("id") or ""))

    reverse = (sortOrder == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    start_index = 0
    if cursor:
        # Cursor is last seen id; start after it if present
        for i, te in enumerate(filtered):
            if te.get("id") == cursor:
                start_index = i + 1
                break

    page = filtered[start_index:start_index + limit]
    has_more = (start_index + limit) < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log(ident.get("id"), workspaceId, "OK", None, extra={"returned": len(page), "total": len(filtered)})
    return {"time_entries": page, "meta": {"total": len(filtered), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def getSummaryReport(workspaceId, start, end, userIds=None, projectIds=None, groupBy=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getSummaryReport"

    ulid_ws = re.compile(r"^ws_[0-9A-HJKMNP-TV-Z]{26}$")
    ulid_usr = re.compile(r"^usr_[0-9A-HJKMNP-TV-Z]{26}$")
    ulid_prj = re.compile(r"^prj_[0-9A-HJKMNP-TV-Z]{26}$")

    def _iso_parse(s):
        if not isinstance(s, str):
            raise ValueError("datetime must be string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    v = v[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None
        return None

    def _log(req_identity_id, req_workspace_id, status_code, message=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        row = {
            "id": f"req_{now.strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "integration_identity_id": req_identity_id,
            "workspace_id": req_workspace_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now.isoformat().replace("+00:00", "Z"),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _pick_identity_for_workspace(ws_id):
        workspaces = _load("workspaces.json")
        ws = next((w for w in workspaces if w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, ws
        identities = _load("integration_identities.json")
        ident = next((i for i in identities if i.get("workspace_id") == ws_id and i.get("status") == "active"), None)
        return ident, ws

    def _rate_limit(identity):
        if not identity:
            return None
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        logs = _load("request_logs.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("integration_identity_id") != identity.get("id"):
                continue
            ts = _to_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= window_start:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit=rpm, window_seconds=60)
        return None

    # --- validation ---
    if not isinstance(workspaceId, str) or not ulid_ws.match(workspaceId):
        _log(None, None, "VALIDATION_ERROR", "Invalid workspaceId.")
        return _err("VALIDATION_ERROR", "Invalid workspaceId.")
    try:
        start_dt = _iso_parse(start)
    except Exception:
        _log(None, workspaceId, "VALIDATION_ERROR", "Malformed start datetime.")
        return _err("VALIDATION_ERROR", "Malformed start datetime.")
    try:
        end_dt = _iso_parse(end)
    except Exception:
        _log(None, workspaceId, "VALIDATION_ERROR", "Malformed end datetime.")
        return _err("VALIDATION_ERROR", "Malformed end datetime.")
    if start_dt > end_dt:
        _log(None, workspaceId, "VALIDATION_ERROR", "Invalid datetime range: start after end.")
        return _err("VALIDATION_ERROR", "Invalid datetime range: start must be <= end.")
    if groupBy is None:
        groupBy = "user_project"
    if groupBy not in ("user", "project", "user_project"):
        _log(None, workspaceId, "VALIDATION_ERROR", "Invalid groupBy.")
        return _err("VALIDATION_ERROR", "Invalid groupBy.")
    if userIds is not None:
        if not isinstance(userIds, list) or any((not isinstance(x, str) or not ulid_usr.match(x)) for x in userIds):
            _log(None, workspaceId, "VALIDATION_ERROR", "Invalid userIds.")
            return _err("VALIDATION_ERROR", "Invalid userIds.")
    if projectIds is not None:
        if not isinstance(projectIds, list) or any((not isinstance(x, str) or not ulid_prj.match(x)) for x in projectIds):
            _log(None, workspaceId, "VALIDATION_ERROR", "Invalid projectIds.")
            return _err("VALIDATION_ERROR", "Invalid projectIds.")

    # --- auth (ambient) ---
    identity, ws = _pick_identity_for_workspace(workspaceId)
    if identity is None:
        _log(None, workspaceId, "UNAUTHORIZED", "No active integration identity for workspace.")
        return _err("UNAUTHORIZED", "No active integration identity available for requested workspace.")
    rl = _rate_limit(identity)
    if rl:
        _log(identity.get("id"), workspaceId, "RATE_LIMIT", "Rate limit exceeded.")
        return rl

    # Validate that filtered ids exist in workspace if provided (NOT_FOUND if any missing)
    users = _load("users.json")
    projects = _load("projects.json")

    ws_users = {u.get("id"): u for u in users if u.get("workspace_id") == workspaceId}
    ws_projects = {p.get("id"): p for p in projects if p.get("workspace_id") == workspaceId}

    if userIds is not None:
        missing = [uid for uid in userIds if uid not in ws_users]
        if missing:
            _log(identity.get("id"), workspaceId, "NOT_FOUND", "One or more users not found in workspace.")
            return _err("NOT_FOUND", "One or more users not found in workspace.", missing_userIds=missing)
    if projectIds is not None:
        missing = [pid for pid in projectIds if pid not in ws_projects]
        if missing:
            _log(identity.get("id"), workspaceId, "NOT_FOUND", "One or more projects not found in workspace.")
            return _err("NOT_FOUND", "One or more projects not found in workspace.", missing_projectIds=missing)

    # Aggregate
    entries = _load("time_entries.json")
    agg = {}  # key -> seconds
    for te in entries:
        if te.get("workspace_id") != workspaceId:
            continue
        if te.get("status") == "deleted":
            continue
        uid = te.get("user_id")
        pid = te.get("project_id")

        if userIds is not None and uid not in set(userIds):
            continue
        if projectIds is not None and pid not in set(projectIds):
            continue

        st = _to_dt(te.get("start_time"))
        en = _to_dt(te.get("end_time"))
        if st is None:
            continue

        # overlap with [start_dt, end_dt)
        if not (st < end_dt):
            continue
        if en is not None and not (en > start_dt):
            continue
        if en is None:
            # running: clip to end_dt using "now" semantics for report: treat as up to min(now,end_dt)
            now = datetime.datetime.now(datetime.timezone.utc)
            en = min(now, end_dt)

        # compute overlap duration in seconds
        clip_start = max(st, start_dt)
        clip_end = min(en, end_dt)
        if clip_end <= clip_start:
            continue
        sec = int((clip_end - clip_start).total_seconds())
        if sec < 0:
            continue

        if groupBy == "user":
            key = (uid, None)
        elif groupBy == "project":
            key = (None, pid)
        else:
            key = (uid, pid)

        agg[key] = agg.get(key, 0) + sec

    # Build response rows, deterministic ordering: by user name then id, then project name then id
    def _user_sort(uid):
        u = ws_users.get(uid) if uid else None
        return ((u.get("name_normalized") if u else ""), (uid or ""))

    def _proj_sort(pid):
        p = ws_projects.get(pid) if pid else None
        return ((p.get("name", "").lower() if p else ""), (pid or ""))

    rows = []
    for (uid, pid), sec in agg.items():
        rows.append({
            "userId": uid,
            "projectId": pid,
            "duration_seconds": sec,
            "hours": sec / 3600.0
        })

    rows.sort(key=lambda r: (_user_sort(r["userId"]), _proj_sort(r["projectId"])))

    resp = {
        "data": {
            "workspaceId": workspaceId,
            "start": start,
            "end": end,
            "groupBy": groupBy,
            "totals": rows,
            "meta": {
                "groups": len(rows),
                "total_duration_seconds": sum(r["duration_seconds"] for r in rows),
                "total_hours": sum(r["hours"] for r in rows),
            }
        }
    }
    _log(identity.get("id"), workspaceId, "OK", None)
    return resp

