            sv_enc = ""
        else:
            sv_enc = _iso_out(sv_dt if sv_dt is not None else last.get(sort_key_field))
        next_cursor = f"{sv_enc}|{last.get('id','')}"

    resp = {
        "data": {
            "matchedUsers": matches,
            "timeEntries": page,
            "pagination": {
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "total": len(filtered) if cursor is None else None
            },
            "sort": {"by": sortBy, "order": sortOrder},
            "match_strategy": "case-insensitive partial match; union of all matched users ordered by name then id",
        }
    }
    _log(identity.get("id"), workspaceId, "OK", None)
    return resp

def updateTimeEntry(workspaceId, timeEntryId, projectId=None, description=None, startTime=None, endTime=None, billable=None, status=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateTimeEntry"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        return prefix + "_" + "".join(_B32[secrets.randbelow(len(_B32))] for _ in range(26))

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field, allow_null=True):
        if s is None and allow_null:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO8601 datetime string or null.")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO8601 datetime.")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _to_iso_z(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(identity_id, ws_id, status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "integration_identity_id": identity_id,
            "workspace_id": ws_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _find_identity_for_workspace(ws_id):
        identities = _load("integration_identities.json")
        if not isinstance(identities, list):
            identities = []
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws_row:
            return None, ws_row
        if ws_row.get("status") == "deleted":
            return None, ws_row
        for ident in identities:
            if isinstance(ident, dict) and ident.get("workspace_id") == ws_id and ident.get("status") == "active":
                return ident, ws_row
        return None, ws_row

    def _rate_limit_check(identity_row):
        limit = identity_row.get("requests_per_minute_limit")
        if not isinstance(limit, int) or limit < 1 or limit > 600:
            return _err("UNAUTHORIZED", "Integration identity is misconfigured (invalid requests_per_minute_limit).")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != identity_row.get("id"):
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            s = ts
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= window_start:
                count += 1
        if count >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded for this integration identity.", limit=limit, window_seconds=60)
        return None

    # Basic type validation without over-rejecting by ULID prefix (business rules enforce via lookups)
    if not isinstance(workspaceId, str) or not workspaceId:
        _log(None, None, 400, "workspaceId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string.")
    if not isinstance(timeEntryId, str) or not timeEntryId:
        _log(None, workspaceId, 400, "timeEntryId must be a non-empty string.")
        return _err("VALIDATION_ERROR", "timeEntryId must be a non-empty string.")
    if projectId is not None and not (isinstance(projectId, str) or projectId is None):
        _log(None, workspaceId, 400, "projectId must be a string or null.")
        return _err("VALIDATION_ERROR", "projectId must be a string or null.")
    if description is not None and not isinstance(description, str):
        _log(None, workspaceId, 400, "description must be a string.")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if billable is not None and not isinstance(billable, bool):
        _log(None, workspaceId, 400, "billable must be a boolean.")
        return _err("VALIDATION_ERROR", "billable must be a boolean.")
    if status is not None and status not in ("running", "stopped", "deleted"):
        _log(None, workspaceId, 400, "status must be one of: running, stopped, deleted.")
        return _err("VALIDATION_ERROR", "status must be one of: running, stopped, deleted.")

    st, e1 = _parse_dt(startTime, "startTime", allow_null=True)
    if e1:
        _log(None, workspaceId, 400, e1["error"]["message"])
        return e1
    et, e2 = _parse_dt(endTime, "endTime", allow_null=True)
    if e2:
        _log(None, workspaceId, 400, e2["error"]["message"])
        return e2

    ident_row, ws_row = _find_identity_for_workspace(workspaceId)
    if not ws_row:
        _log(None, workspaceId, 404, "Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if ws_row.get("status") == "deleted":
        _log(None, workspaceId, 401, "Workspace connection is deleted.")
        return _err("UNAUTHORIZED", "Workspace connection is deleted.")
    if not ident_row:
        _log(None, workspaceId, 401, "No active integration identity available for this workspace.")
        return _err("UNAUTHORIZED", "No active integration identity available for this workspace.")

    rl = _rate_limit_check(ident_row)
    if rl:
        _log(ident_row.get("id"), workspaceId, 429, rl["error"]["message"])
        return rl

    time_entries = _load("time_entries.json")
    if not isinstance(time_entries, list):
        time_entries = []
    idx = None
    row = None
    for i, te in enumerate(time_entries):
        if isinstance(te, dict) and te.get("id") == timeEntryId:
            idx = i
            row = te
            break
    if row is None:
        _log(ident_row.get("id"), workspaceId, 404, "Time entry not found.")
        return _err("NOT_FOUND", "Time entry not found.")
    if row.get("workspace_id") != workspaceId:
        _log(ident_row.get("id"), workspaceId, 409, "Time entry does not belong to the specified workspace.")
        return _err("CONFLICT", "Time entry does not belong to the specified workspace (FK integrity).")
    if row.get("status") == "deleted":
        _log(ident_row.get("id"), workspaceId, 409, "Cannot edit a deleted time entry.")
        return _err("INVALID_TRANSITION", "Cannot edit a deleted time entry (status is terminal).")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Apply project update (allow explicit null)
    if projectId is not None:
        if projectId is None:
            row["project_id"] = None
        else:
            pr = next((p for p in projects if isinstance(p, dict) and p.get("id") == projectId), None)
            if not pr:
                _log(ident_row.get("id"), workspaceId, 404, "Project not found.")
                return _err("NOT_FOUND", "Project not found.")
            if pr.get("workspace_id") != workspaceId:
                _log(ident_row.get("id"), workspaceId, 409, "Project does not belong to the specified workspace.")
                return _err("CONFLICT", "Project does not belong to the specified workspace (FK integrity).")
            row["project_id"] = projectId

    if description is not None:
        row["description"] = description
    if billable is not None:
        row["billable"] = billable

    # Parse existing times
    cur_st, pe1 = _parse_dt(row.get("start_time"), "start_time", allow_null=False)
    if pe1:
        _log(ident_row.get("id"), workspaceId, 409, "Stored start_time is invalid.")
        return _err("CONFLICT", "Stored start_time is invalid.")
    cur_et, pe2 = _parse_dt(row.get("end_time"), "end_time", allow_null=True)
    if pe2:
        _log(ident_row.get("id"), workspaceId, 409, "Stored end_time is invalid.")
        return _err("CONFLICT", "Stored end_time is invalid.")

    new_st = st if st is not None else cur_st
    new_et = et if endTime is not None else cur_et  # differentiate omitted vs provided null; if endTime param is None it's "provided null" in this signature. treat as provided.
    # In Python signature, caller passes endTime=None explicitly or omit. We can't distinguish reliably. We'll treat None as "set null" only if status indicates running; otherwise keep.
    if endTime is None and status is None and startTime is not None:
        new_et = cur_et

    # Handle lifecycle transitions
    transitions = {
        "running": {"stopped", "deleted"},
        "stopped": {"deleted"},
        "deleted": set(),
    }
    cur_status = row.get("status")
    if cur_status not in transitions:
        _log(ident_row.get("id"), workspaceId, 409, "Stored status is invalid.")
        return _err("CONFLICT", "Stored status is invalid.")

    target_status = cur_status
    if status is not None:
        if status != cur_status:
            if status not in transitions.get(cur_status, set()):
                _log(ident_row.get("id"), workspaceId, 409, f"Illegal status transition {cur_status} -> {status}.")
                return _err("INVALID_TRANSITION", f"Illegal status transition: {cur_status} -> {status}.")
            target_status = status

    # Status implies time fields
    if target_status == "running":
        new_et = None
    elif target_status == "stopped":
        # If switching to stopped and end time not provided, default to now
        if new_et is None:
            new_et = datetime.datetime.now(datetime.timezone.utc)

    if new_et is not None and new_et < new_st:
        _log(ident_row.get("id"), workspaceId, 400, "endTime must be greater than or equal to startTime.")
        return _err("VALIDATION_ERROR", "endTime must be greater than or equal to startTime.")

    # Only one running time entry per user per workspace
    if target_status == "running":
        for te in time_entries:
            if not isinstance(te, dict):
                continue
            if te.get("id") == row.get("id"):
                continue
            if te.get("workspace_id") == workspaceId and te.get("user_id") == row.get("user_id") and te.get("status") == "running":
                _log(ident_row.get("id"), workspaceId, 409, "A running time entry already exists for this user in this workspace.")
                return _err("CONFLICT", "Only one running time entry per user per workspace is allowed.")

    # FK integrity for user still valid and within workspace
    urow = next((u for u in users if isinstance(u, dict) and u.get("id") == row.get("user_id")), None)
    if not urow:
        _log(ident_row.get("id"), workspaceId, 409, "Time entry references a user that does not exist.")
        return _err("CONFLICT", "Time entry references a user that does not exist (FK integrity).")
    if urow.get("workspace_id") != workspaceId:
        _log(ident_row.get("id"), workspaceId, 409, "Time entry user does not belong to the specified workspace.")
        return _err("CONFLICT", "Time entry user does not belong to the specified workspace (FK integrity).")

    # Compute duration_seconds
    if target_status == "running":
        dur = None
    else:
        dur = int((new_et - new_st).total_seconds()) if new_et is not None else None
        if dur is not None and dur < 0:
            _log(ident_row.get("id"), workspaceId, 409, "Computed duration must be non-negative.")
            return _err("CONFLICT", "Computed duration must be non-negative.")

    # Enforce status->end_time constraints
    if target_status == "running" and new_et is not None:
        _log(ident_row.get("id"), workspaceId, 409, "Business rule violated: running entry must have null end_time.")
        return _err("CONFLICT", "Business rule violated: status='running' implies end_time is null.")
    if target_status == "stopped" and new_et is None:
        _log(ident_row.get("id"), workspaceId, 409, "Business rule violated: stopped entry must have end_time.")
        return _err("CONFLICT", "Business rule violated: status='stopped' implies end_time is not null.")

    # Apply updates
    row["start_time"] = _to_iso_z(new_st)
    row["end_time"] = _to_iso_z(new_et)
    row["duration_seconds"] = dur
    row["status"] = target_status
    row["updated_at"] = _now_iso()

    time_entries[idx] = row
    _save("time_entries.json", time_entries)

    _log(ident_row.get("id"), workspaceId, 200, None, extra={"time_entry_id": row["id"]})
    return {"timeEntry": row}

def getIntegrationIdentity(integrationIdentityId=None, workspaceId=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getIntegrationIdentity"

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        return prefix + "_" + "".join(_B32[secrets.randbelow(len(_B32))] for _ in range(26))

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(identity_id, ws_id, status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "endpoint": endpoint,
            "integration_identity_id": identity_id,
            "workspace_id": ws_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate(identity):
        rpm = identity.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
            return _err("VALIDATION_ERROR", "Integration identity has invalid requests_per_minute_limit.")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != identity.get("id"):
                continue
            ts = r.get("created_at") or r.get("timestamp")
            if not isinstance(ts, str):
                continue
            ss = ts.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(ss)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            if dt >= cutoff:
                used += 1
        if used >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", limit_per_minute=rpm, used_last_minute=used)
        return None

    def _resolve_identity():
        identities = _load("integration_identities.json")
        workspaces = _load("workspaces.json")
        if not isinstance(identities, list):
            identities = []
        if not isinstance(workspaces, list):
            workspaces = []

        def ws_active(ws_id):
            return any(isinstance(w, dict) and w.get("id") == ws_id and w.get("status") == "active" for w in workspaces)

        # If caller provided an id, accept either exact match or if they mistakenly pass a workspace id, fall back to workspace resolution.
        if isinstance(integrationIdentityId, str) and integrationIdentityId:
            ident = next((i for i in identities if isinstance(i, dict) and i.get("id") == integrationIdentityId and i.get("status") == "active"), None)
            if ident and ws_active(ident.get("workspace_id")):
                return ident
            # fallback: treat provided value as workspace id and find an active identity within it
            ident2 = next((i for i in identities if isinstance(i, dict) and i.get("workspace_id") == integrationIdentityId and i.get("status") == "active" and ws_active(i.get("workspace_id"))), None)
            if ident2:
                return ident2

        # If workspaceId provided, use it
        if isinstance(workspaceId, str) and workspaceId:
            ident = next((i for i in identities if isinstance(i, dict) and i.get("workspace_id") == workspaceId and i.get("status") == "active" and ws_active(workspaceId)), None)
            if ident:
                return ident

        # Ambient auth: pick any active identity whose workspace is active (must not fail just because no explicit credential param exists)
        candidates = [i for i in identities if isinstance(i, dict) and i.get("status") == "active" and ws_active(i.get("workspace_id"))]
        # deterministic
        candidates.sort(key=lambda r: (str(r.get("workspace_id") or ""), str(r.get("id") or "")))
        return candidates[0] if candidates else None

    ident = _resolve_identity()
    if not ident:
        _log(None, workspaceId, "UNAUTHORIZED", "No valid integration identity is authenticated.")
        return _err("UNAUTHORIZED", "No valid integration identity is authenticated.")

    # Optional assertion of workspace scope
    if isinstance(workspaceId, str) and workspaceId and ident.get("workspace_id") != workspaceId:
        _log(ident.get("id"), workspaceId, "UNAUTHORIZED", "Authenticated identity is not scoped to the requested workspace.")
        return _err("UNAUTHORIZED", "Authenticated identity is not scoped to the requested workspace.")

    rate_err = _enforce_rate(ident)
    if rate_err:
        _log(ident.get("id"), ident.get("workspace_id"), "RATE_LIMIT", rate_err["error"]["message"])
        return rate_err

    # Include workspace info + rate info
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ident.get("workspace_id")), None)

    body = {
        "integration_identity": ident,
        "workspace": ws,
        "rate_limit": {
            "requests_per_minute_limit": ident.get("requests_per_minute_limit"),
        },
    }
    _log(ident.get("id"), ident.get("workspace_id"), "OK", None)
    return body

def updateWorkspace(workspaceId, name=None, defaultTimezone=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0369000" if __import__("os").path.isdir("./environment_mix/0369000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _B32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid_like():
        import secrets
        return "".join(_B32[secrets.randbelow(len(_B32))] for _ in range(26))

    def _ensure_request_log_store():
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            try:
                _save(fname, [])
            except Exception:
                pass
        return fname

    def _log_request(identity_id, endpoint, status_code, latency_ms, reason=None, ws_id=None):
        fname = _ensure_request_log_store()
        logs = _load(fname)
        row = {
            "id": "rl_" + _new_ulid_like(),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "integration_identity_id": identity_id,
            "workspace_id": ws_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
        }
        if reason:
            row["reason"] = reason
        logs.append(row)
        _save(fname, logs)

    def _match_ulid(prefix, s):
        if not isinstance(s, str):
            return False
        return re.match(r"^" + re.escape(prefix) + r"_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _rate_limit_check(identity_row):
        limit = identity_row.get("requests_per_minute_limit")
        if not isinstance(limit, int) or not (1 <= limit <= 600):
            limit = 60
        fname = _ensure_request_log_store()
        logs = _load(fname)
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        used = 0
        iid = identity_row.get("id")
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_identity_id") != iid:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= window_start:
                used += 1
        remaining = max(0, limit - used)
        reset_at = (window_start + datetime.timedelta(seconds=60)).isoformat()
        return {"limit": limit, "used": used, "remaining": remaining, "reset_at": reset_at}, (used >= limit)

    def _resolve_ambient_identity(iids, ws_rows, target_ws_id):
        # Find an active identity scoped to this workspace whose workspace isn't deleted.
        for r in iids:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            if r.get("workspace_id") != target_ws_id:
                continue
            w = next((x for x in ws_rows if x.get("id") == target_ws_id), None)
            if not w or w.get("status") == "deleted":
                continue
            return r, w
        return None, None

    t0 = time.time()

    # Validate workspaceId
    if not _match_ulid("ws", workspaceId):
        return _err("VALIDATION_ERROR", "Invalid workspaceId format; expected ULID like ws_01H...")

    # Validate fields
    if name is not None and (not isinstance(name, str) or name == ""):
        return _err("VALIDATION_ERROR", "Invalid name; must be a non-empty string.")
    if defaultTimezone is not None and (not isinstance(defaultTimezone, str) or defaultTimezone.strip() == ""):
        return _err("VALIDATION_ERROR", "Invalid defaultTimezone; must be a non-empty IANA timezone string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status; must be one of: active, suspended, deleted.")

    # Load data
    wss = _load("workspaces.json")
    iids = _load("integration_identities.json")

    # Find workspace
    ws_idx = None
    for i, w in enumerate(wss):
        if isinstance(w, dict) and w.get("id") == workspaceId:
            ws_idx = i
            break
    if ws_idx is None:
        # No success without effect
        try:
            _log_request(None, "updateWorkspace", "NOT_FOUND", (time.time() - t0) * 1000, reason="workspace_missing", ws_id=workspaceId)
        except Exception:
            pass
        return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    # Resolve ambient identity that is scoped to the workspace
    identity, _ = _resolve_ambient_identity(iids, wss, workspaceId)
    if not identity:
        try:
            _log_request(None, "updateWorkspace", "UNAUTHORIZED", (time.time() - t0) * 1000, reason="no_scoped_active_identity", ws_id=workspaceId)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Authenticated integration identity is not scoped to this workspace, or is revoked.")

    # Rate limit check before mutation
    rate, limited = _rate_limit_check(identity)
    if limited:
        try:
            _log_request(identity.get("id"), "updateWorkspace", "RATE_LIMIT", (time.time() - t0) * 1000, reason="rpm_exceeded", ws_id=workspaceId)
        except Exception:
            pass
        return _err("RATE_LIMIT", "Rate limit exceeded for integration identity.", rate_limit=rate)

    ws = wss[ws_idx]
    old_status = ws.get("status")

    # Validate lifecycle transition
    if status is not None:
        transitions = {
            "active": ["suspended", "deleted"],
            "suspended": ["active", "deleted"],
            "deleted": [],
        }
        if old_status not in transitions:
            try:
                _log_request(identity.get("id"), "updateWorkspace", "VALIDATION_ERROR", (time.time() - t0) * 1000, reason="invalid_current_status", ws_id=workspaceId)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "Workspace has invalid current status in store.", currentStatus=old_status)
        if status != old_status:
            if status not in transitions.get(old_status, []):
                # Specifically refuse reactivating deleted workspace
                code = "INVALID_TRANSITION"
                msg = "Invalid status transition."
                if old_status == "deleted" and status in ("active", "suspended"):
                    msg = "Cannot reactivate a deleted workspace."
                try:
                    _log_request(identity.get("id"), "updateWorkspace", code, (time.time() - t0) * 1000, reason="invalid_transition", ws_id=workspaceId)
                except Exception:
                    pass
                return _err(code, msg, fromStatus=old_status, toStatus=status)

    # Apply updates; ensure at least one change
    changed = False
    if name is not None and name != ws.get("name"):
        ws["name"] = name
        changed = True
    if defaultTimezone is not None and defaultTimezone != ws.get("default_timezone"):
        ws["default_timezone"] = defaultTimezone
        changed = True
    if status is not None and status != ws.get("status"):
        ws["status"] = status
        changed = True

    if not changed:
        # Idempotent: still counts as a request and returns current workspace
        try:
            _log_request(identity.get("id"), "updateWorkspace", "OK", (time.time() - t0) * 1000, ws_id=workspaceId)
        except Exception:
            pass
        return {
            "workspace": {
                "id": ws.get("id"),
                "clockifyWorkspaceId": ws.get("clockify_workspace_id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "defaultTimezone": ws.get("default_timezone"),
                "createdAt": ws.get("created_at"),
                "updatedAt": ws.get("updated_at"),
            },
            "rateLimit": rate,
        }

    # Enforce constraints: name <> ''
    if not isinstance(ws.get("name"), str) or ws.get("name") == "":
        try:
            _log_request(identity.get("id"), "updateWorkspace", "VALIDATION_ERROR", (time.time() - t0) * 1000, reason="name_constraint", ws_id=workspaceId)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Workspace name must be a non-empty string.")

    ws["updated_at"] = _now_iso()
    wss[ws_idx] = ws
    _save("workspaces.json", wss)

    try:
        _log_request(identity.get("id"), "updateWorkspace", "OK", (time.time() - t0) * 1000, ws_id=workspaceId)
    except Exception:
        pass

    return {
        "workspace": {
            "id": ws.get("id"),
            "clockifyWorkspaceId": ws.get("clockify_workspace_id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "defaultTimezone": ws.get("default_timezone"),
            "createdAt": ws.get("created_at"),
            "updatedAt": ws.get("updated_at"),
        },
        "rateLimit": rate,
    }
